/* Question bank — CFA-style single-best-answer (3 options).
 * Each: { id, topicId, moduleId, difficulty (1 basic/2 intermediate/3 exam),
 *         stem, options:[A,B,C], answer: correct index, explanation, ref }.
 * Options are shuffled at render time. Start small and grow — just append objects. */
window.QUESTIONS = [

  /* ---------- Ethics ---------- */
  { id: 'q-eth-001', topicId: 'ethics', moduleId: 'eth-3', difficulty: 1, stem: 'When applicable law and the CFA Institute Code and Standards conflict, a member must comply with:', options: ['the applicable local law in every case', 'the stricter of the law and the Code and Standards', 'the Code and Standards in every case'], answer: 1, explanation: 'Standard I(A): follow the strictest applicable rule. If the law is stricter, follow the law; otherwise follow the Code and Standards.', ref: 'LOS eth-3-a' },
  { id: 'q-eth-002', topicId: 'ethics', moduleId: 'eth-4', difficulty: 2, stem: 'Combining several pieces of non-material nonpublic information with public information to reach a conclusion is best described as:', options: ['a violation of Standard II(A)', 'the mosaic theory, which is permitted', 'market manipulation'], answer: 1, explanation: 'The mosaic theory is explicitly allowed — conclusions built from public plus non-material nonpublic pieces are not MNPI violations.', ref: 'LOS eth-4-a' },
  { id: 'q-eth-003', topicId: 'ethics', moduleId: 'eth-5', difficulty: 2, stem: 'Under Standard III(C) Suitability, an investment’s suitability should be judged:', options: ['on a standalone, security-by-security basis', 'in the context of the client’s total portfolio', 'relative to the manager’s model portfolio'], answer: 1, explanation: 'Suitability is assessed at the portfolio level — a risky security may be suitable within a diversified portfolio.', ref: 'LOS eth-5-a' },
  { id: 'q-eth-004', topicId: 'ethics', moduleId: 'eth-3', difficulty: 2, stem: 'A member receives an expensive watch from a client as a reward for strong performance last year. The member should:', options: ['refuse the gift in all cases', 'disclose it to the employer and may accept it', 'accept it only if it is under a set monetary threshold'], answer: 1, explanation: 'Gifts from clients for past performance may be accepted with disclosure to the employer; gifts from issuers/third parties that could bias judgment should be refused.', ref: 'LOS eth-3-a' },
  { id: 'q-eth-005', topicId: 'ethics', moduleId: 'eth-7', difficulty: 1, stem: 'If no regulatory requirement applies, CFA Institute recommends retaining records supporting analysis for at least:', options: ['5 years', '7 years', '10 years'], answer: 1, explanation: 'Standard V(C): a seven-year minimum is the recommended default retention period; records are the firm’s property.', ref: 'LOS eth-7-a' },
  { id: 'q-eth-006', topicId: 'ethics', moduleId: 'eth-9', difficulty: 1, stem: 'Which statement about the CFA designation is acceptable?', options: ['"He is a CFA with 10 years of experience."', '"She earned the right to use the CFA designation."', '"As a CFA, I consistently beat the market."'], answer: 1, explanation: 'CFA must be used as an adjective, never a noun, and it may not be tied to claims of superior performance.', ref: 'LOS eth-9-b' },
  { id: 'q-eth-007', topicId: 'ethics', moduleId: 'eth-8', difficulty: 2, stem: 'A manager personally buys a stock just before placing large client orders in the same stock. This most directly violates:', options: ['Standard VI(B) Priority of Transactions', 'Standard III(D) Performance Presentation', 'Standard VII(A) Conduct in the CFA Program'], answer: 0, explanation: 'Clients come before personal transactions; trading ahead of clients (front-running) violates VI(B).', ref: 'LOS eth-8-a' },
  { id: 'q-eth-008', topicId: 'ethics', moduleId: 'eth-6', difficulty: 2, stem: 'An analyst leaves her employer. With respect to a client contact list she built while employed there, she may:', options: ['take the list, since she created it', 'not take it; records are the employer’s property', 'take only the email addresses'], answer: 1, explanation: 'Standard IV(A): records and client lists compiled during employment belong to the employer unless agreed otherwise.', ref: 'LOS eth-6-a' },

  /* ---------- Quantitative Methods ---------- */
  { id: 'q-qm-001', topicId: 'quant', moduleId: 'qm-4', difficulty: 1, stem: 'A stated annual rate of 12% compounded monthly has an effective annual rate closest to:', options: ['12.00%', '12.68%', '12.36%'], answer: 1, explanation: 'EAR = (1 + 0.12/12)¹² − 1 = 1.01¹² − 1 = 12.68%.', ref: 'LOS qm-4-a' },
  { id: 'q-qm-002', topicId: 'quant', moduleId: 'qm-5', difficulty: 2, stem: 'For a return series with a long right tail, the most likely ordering is:', options: ['mean > median > mode', 'mode > median > mean', 'median > mean > mode'], answer: 0, explanation: 'Positive skew pulls the mean above the median, which sits above the mode.', ref: 'LOS qm-5-a' },
  { id: 'q-qm-003', topicId: 'quant', moduleId: 'qm-9', difficulty: 2, stem: 'The probability of a Type I error equals:', options: ['the p-value', 'the significance level α', 'one minus the power of the test'], answer: 1, explanation: 'α is set by the researcher and is the probability of rejecting a true null. 1 − power = P(Type II error).', ref: 'LOS qm-9-a' },
  { id: 'q-qm-004', topicId: 'quant', moduleId: 'qm-2', difficulty: 2, stem: 'An investor buys $1,000 of a fund each month at prices 10, 12.50 and 8. The average price paid per share is best measured by the:', options: ['arithmetic mean (10.17)', 'harmonic mean (9.84)', 'geometric mean (10.00)'], answer: 1, explanation: 'Equal dollar amounts each period → harmonic mean, which lies below the arithmetic mean.', ref: 'LOS qm-2-a' },
  { id: 'q-qm-005', topicId: 'quant', moduleId: 'qm-8', difficulty: 1, stem: 'A 95% confidence interval for a normally distributed variable is approximately the mean plus or minus:', options: ['1.65 standard deviations', '1.96 standard deviations', '2.58 standard deviations'], answer: 1, explanation: '90% → 1.65, 95% → 1.96, 99% → 2.58.', ref: 'LOS qm-8-a' },
  { id: 'q-qm-006', topicId: 'quant', moduleId: 'qm-6', difficulty: 1, stem: 'How many ways can a committee of 3 be chosen from 8 people when order does not matter?', options: ['336', '56', '24'], answer: 1, explanation: '8C3 = 8!/(5!·3!) = 56. 336 would be the permutation 8P3.', ref: 'LOS qm-6-a' },
  { id: 'q-qm-007', topicId: 'quant', moduleId: 'qm-8', difficulty: 1, stem: 'The standard error of the sample mean:', options: ['increases with sample size', 'decreases with sample size', 'is unaffected by sample size'], answer: 1, explanation: 'SE = σ/√n — larger samples give a more precise estimate of the mean.', ref: 'LOS qm-8-a' },
  { id: 'q-qm-008', topicId: 'quant', moduleId: 'qm-9', difficulty: 2, stem: 'An analyst computes a p-value of 0.03 for a test at the 5% significance level. She should:', options: ['fail to reject H₀', 'reject H₀', 'accept H₀'], answer: 1, explanation: 'p-value 0.03 < α 0.05 → reject H₀. We never "accept" a null, only fail to reject it.', ref: 'LOS qm-9-a' },
  { id: 'q-qm-009', topicId: 'quant', moduleId: 'qm-7', difficulty: 2, stem: 'Resampling a data set with replacement to build a sampling distribution is called:', options: ['Monte Carlo simulation', 'bootstrapping', 'historical simulation'], answer: 1, explanation: 'Bootstrapping resamples the observed data with replacement; Monte Carlo draws from an assumed distribution; historical simulation uses the actual past path.', ref: 'LOS qm-7-a' },
  { id: 'q-qm-010', topicId: 'quant', moduleId: 'qm-10', difficulty: 2, stem: 'In a simple linear regression, the coefficient of determination (R²) measures:', options: ['the statistical significance of the slope', 'the fraction of the variation in Y explained by X', 'the slope of the regression line'], answer: 1, explanation: 'R² is the proportion of total variation in the dependent variable explained by the model.', ref: 'LOS qm-10-a' },
  { id: 'q-qm-011', topicId: 'quant', moduleId: 'qm-11', difficulty: 2, stem: 'Grouping unlabeled companies into clusters by financial characteristics is an example of:', options: ['supervised learning', 'unsupervised learning', 'reinforcement of a labeled target'], answer: 1, explanation: 'Clustering has no labeled target variable → unsupervised learning. Supervised learning predicts a labeled output.', ref: 'LOS qm-11-a' },
  { id: 'q-qm-012', topicId: 'quant', moduleId: 'qm-11', difficulty: 2, stem: 'A key risk when using a large language model to summarize financial disclosures is that it may:', options: ['always refuse to answer', 'generate plausible but false statements (hallucinate)', 'only work on numeric data'], answer: 1, explanation: 'LLMs can hallucinate — produce fluent but incorrect content — so outputs need human verification and governance.', ref: 'LOS qm-11-a' },
  { id: 'q-qm-013', topicId: 'quant', moduleId: 'qm-3', difficulty: 2, stem: 'A valid performance benchmark should be all of the following EXCEPT:', options: ['specified in advance', 'investable', 'chosen after the measurement period to best fit results'], answer: 2, explanation: 'A benchmark must be specified in advance (among other properties). Choosing it after the fact to fit results is invalid.', ref: 'LOS qm-3-a' },

  /* ---------- Economics ---------- */
  { id: 'q-econ-001', topicId: 'econ', moduleId: 'econ-1', difficulty: 1, stem: 'If the cross-price elasticity between goods X and Y is +1.4, the goods are:', options: ['complements', 'substitutes', 'inferior goods'], answer: 1, explanation: 'A rise in the price of Y raises demand for X → substitutes. Negative cross-price elasticity indicates complements.', ref: 'LOS econ-1-a' },
  { id: 'q-econ-002', topicId: 'econ', moduleId: 'econ-1', difficulty: 2, stem: 'In long-run equilibrium under monopolistic competition, firms earn:', options: ['positive economic profit', 'zero economic profit with price above marginal cost', 'zero economic profit with price equal to marginal cost'], answer: 1, explanation: 'Entry drives economic profit to zero, but product differentiation keeps P > MC (unlike perfect competition).', ref: 'LOS econ-1-a' },
  { id: 'q-econ-003', topicId: 'econ', moduleId: 'econ-2', difficulty: 1, stem: 'Which is a leading economic indicator?', options: ['average duration of unemployment', 'building permits for new houses', 'industrial production'], answer: 1, explanation: 'Permits lead activity. Industrial production is coincident; unemployment duration is lagging.', ref: 'LOS econ-2-a' },
  { id: 'q-econ-004', topicId: 'econ', moduleId: 'econ-4', difficulty: 2, stem: 'According to money neutrality, in the long run an increase in the money supply affects:', options: ['real output only', 'the price level only', 'both output and prices proportionally'], answer: 1, explanation: 'Long-run money growth feeds into prices; real variables are set by real factors.', ref: 'LOS econ-4-a' },
  { id: 'q-econ-005', topicId: 'econ', moduleId: 'econ-8', difficulty: 2, stem: 'Spot USD/EUR = 1.1000. One-year rates: USD 5%, EUR 3%. The one-year forward USD/EUR is closest to:', options: ['1.0790', '1.1214', '1.1000'], answer: 1, explanation: 'F = 1.10 × 1.05/1.03 = 1.1214. The euro (lower rate, base currency) trades at a forward premium.', ref: 'LOS econ-8-a' },
  { id: 'q-econ-006', topicId: 'econ', moduleId: 'econ-6', difficulty: 1, stem: 'A country with an absolute disadvantage in producing all goods can still gain from trade because of:', options: ['economies of scale', 'comparative advantage', 'currency depreciation'], answer: 1, explanation: 'What matters is relative opportunity cost — specialise where the opportunity cost is lowest.', ref: 'LOS econ-6-a' },
  { id: 'q-econ-007', topicId: 'econ', moduleId: 'econ-3', difficulty: 3, stem: 'Expansionary fiscal policy combined with restrictive monetary policy most likely produces:', options: ['lower interest rates and a smaller public sector', 'higher interest rates and a larger public sector', 'lower output and lower interest rates'], answer: 1, explanation: 'Government spending expands the public sector while tight money pushes rates up (crowding out intensifies).', ref: 'LOS econ-3-a' },
  { id: 'q-econ-008', topicId: 'econ', moduleId: 'econ-5', difficulty: 2, stem: 'A country that chooses economic self-sufficiency and avoids international trade is pursuing:', options: ['globalization', 'autarky', 'a currency peg'], answer: 1, explanation: 'Autarky = self-sufficiency / non-cooperation; the opposite of globalization.', ref: 'LOS econ-5-a' },

  /* ---------- FSA ---------- */
  { id: 'q-fsa-001', topicId: 'fsa', moduleId: 'fsa-6', difficulty: 2, stem: 'During a period of rising prices, LIFO (vs FIFO) results in:', options: ['higher net income and higher inventory', 'lower net income and lower inventory', 'lower net income and higher inventory'], answer: 1, explanation: 'LIFO charges the newest (most expensive) units to COGS: income and ending inventory are both lower; taxes are lower too.', ref: 'LOS fsa-6-a' },
  { id: 'q-fsa-002', topicId: 'fsa', moduleId: 'fsa-4', difficulty: 1, stem: 'Under US GAAP, dividends paid are classified in the cash flow statement as:', options: ['operating', 'financing', 'investing'], answer: 1, explanation: 'US GAAP: dividends paid = CFF; interest paid/received and dividends received = CFO. IFRS allows choices.', ref: 'LOS fsa-4-b' },
  { id: 'q-fsa-003', topicId: 'fsa', moduleId: 'fsa-7', difficulty: 2, stem: 'Capitalizing rather than expensing a cost in the year of the expenditure most likely:', options: ['decreases CFO and increases net income', 'increases CFO and increases net income', 'increases CFO and decreases net income'], answer: 1, explanation: 'The outflow moves to CFI (so CFO looks stronger), and only depreciation hits income — net income is higher initially.', ref: 'LOS fsa-7-b' },
  { id: 'q-fsa-004', topicId: 'fsa', moduleId: 'fsa-9', difficulty: 2, stem: 'A deferred tax liability typically arises when:', options: ['tax depreciation is slower than book depreciation', 'tax depreciation is faster than book depreciation', 'a firm records a valuation allowance'], answer: 1, explanation: 'Faster tax depreciation → lower taxes now, higher later → a liability for future taxes.', ref: 'LOS fsa-9-a' },
  { id: 'q-fsa-005', topicId: 'fsa', moduleId: 'fsa-11', difficulty: 1, stem: 'Revenue = 500, COGS = 300, average inventory = 60. Days of inventory on hand is closest to:', options: ['44 days', '73 days', '110 days'], answer: 1, explanation: 'Turnover = 300/60 = 5; DOH = 365/5 = 73 days.', ref: 'LOS fsa-11-a' },
  { id: 'q-fsa-006', topicId: 'fsa', moduleId: 'fsa-11', difficulty: 2, stem: 'Which change increases ROE under the 3-way DuPont, all else equal?', options: ['lower financial leverage', 'higher asset turnover', 'lower net profit margin'], answer: 1, explanation: 'ROE = margin × turnover × leverage; raising any factor raises ROE.', ref: 'LOS fsa-11-b' },
  { id: 'q-fsa-007', topicId: 'fsa', moduleId: 'fsa-7', difficulty: 2, stem: 'Under IFRS, a previously impaired machine held for use recovers value. The firm:', options: ['may reverse the impairment up to the original carrying amount (net of depreciation)', 'must not reverse the impairment', 'recognizes the full recovery in other comprehensive income'], answer: 0, explanation: 'IFRS permits impairment reversal for assets held for use (capped); US GAAP prohibits it.', ref: 'LOS fsa-7-a' },
  { id: 'q-fsa-008', topicId: 'fsa', moduleId: 'fsa-5', difficulty: 2, stem: 'Net income 100, depreciation 20, increase in receivables 15, increase in accounts payable 10. Operating cash flow (indirect) is closest to:', options: ['145', '115', '95'], answer: 1, explanation: 'CFO = 100 + 20 − 15 + 10 = 115. Growing receivables consume cash; growing payables provide it.', ref: 'LOS fsa-5-a' },
  { id: 'q-fsa-009', topicId: 'fsa', moduleId: 'fsa-3', difficulty: 3, stem: 'The current ratio is 1.6. Paying off accounts payable with cash will:', options: ['increase the current ratio', 'decrease the current ratio', 'leave it unchanged'], answer: 0, explanation: 'When the ratio is above 1, shrinking both CA and CL equally raises it: (CA−x)/(CL−x) > CA/CL.', ref: 'LOS fsa-3-b' },
  { id: 'q-fsa-010', topicId: 'fsa', moduleId: 'fsa-8', difficulty: 2, stem: 'For a lessee under US GAAP, an operating lease produces on the income statement:', options: ['depreciation plus interest expense', 'a single straight-line lease expense', 'no expense until payments are made'], answer: 1, explanation: 'US GAAP operating leases: one straight-line operating expense. Finance leases split depreciation + interest (front-loaded).', ref: 'LOS fsa-8-a' },

  /* ---------- Corporate Issuers ---------- */
  { id: 'q-ci-001', topicId: 'corp', moduleId: 'ci-5', difficulty: 2, stem: 'When NPV and IRR rank two mutually exclusive projects differently, the firm should choose based on:', options: ['IRR, because it is a percentage', 'NPV, because it measures the addition to shareholder wealth', 'the shorter payback period'], answer: 1, explanation: 'NPV directly measures value creation and assumes reinvestment at the cost of capital.', ref: 'LOS ci-5-a' },
  { id: 'q-ci-002', topicId: 'corp', moduleId: 'ci-5', difficulty: 2, stem: 'Which cash flow is relevant to a capital budgeting decision?', options: ['sunk R&D already spent', 'the opportunity cost of land the firm already owns', 'fixed overhead unaffected by the project'], answer: 1, explanation: 'Opportunity costs are incremental; sunk costs and unaffected overhead are not.', ref: 'LOS ci-5-a' },
  { id: 'q-ci-003', topicId: 'corp', moduleId: 'ci-5', difficulty: 3, stem: 'A project with cash flows that change sign twice most likely has:', options: ['no computable IRR', 'multiple IRRs', 'an IRR equal to the cost of capital'], answer: 1, explanation: 'Each sign change can add a root — with two changes there may be two IRRs (or none).', ref: 'LOS ci-5-a' },
  { id: 'q-ci-004', topicId: 'corp', moduleId: 'ci-6', difficulty: 2, stem: 'In computing WACC, the weights should be based on:', options: ['book values of debt and equity', 'target capital structure at market values', 'the financing mix of the specific project'], answer: 1, explanation: 'Use the firm’s target (market-value-based) proportions, not book values.', ref: 'LOS ci-6-a' },
  { id: 'q-ci-005', topicId: 'corp', moduleId: 'ci-7', difficulty: 2, stem: 'EBIT = 400, interest = 80. The degree of financial leverage is closest to:', options: ['1.25', '1.20', '0.80'], answer: 0, explanation: 'DFL = EBIT/(EBIT − I) = 400/320 = 1.25: a 10% EBIT rise lifts EPS 12.5%.', ref: 'LOS ci-7-a' },
  { id: 'q-ci-006', topicId: 'corp', moduleId: 'ci-7', difficulty: 2, stem: 'Under pecking-order theory, managers prefer to finance new projects first with:', options: ['new equity', 'internally generated funds', 'convertible debt'], answer: 1, explanation: 'Order: internal funds, then debt, then equity last (equity issuance signals overvaluation).', ref: 'LOS ci-7-a' },
  { id: 'q-ci-007', topicId: 'corp', moduleId: 'ci-3', difficulty: 1, stem: 'Which board feature is considered best practice for governance?', options: ['a staggered (classified) board', 'a majority of independent directors', 'the CEO also serving as board chair'], answer: 1, explanation: 'Independence supports objective oversight; staggered boards entrench management and a combined CEO/chair concentrates power.', ref: 'LOS ci-3-a' },
  { id: 'q-ci-008', topicId: 'corp', moduleId: 'ci-4', difficulty: 3, stem: 'A customer on terms 1/10 net 30 who always pays on day 30 bears an implicit annual cost closest to:', options: ['12.3%', '20.1%', '44.6%'], answer: 1, explanation: '(1 + 0.01/0.99)^(365/20) − 1 ≈ 20.1%.', ref: 'LOS ci-4-a' },

  /* ---------- Equities ---------- */
  { id: 'q-eq-001', topicId: 'equity', moduleId: 'eq-1', difficulty: 2, stem: 'A stop-sell order at $45 on a stock trading at $50 will:', options: ['execute immediately at $45', 'become a market order if the price falls to $45', 'guarantee execution at $45 or better'], answer: 1, explanation: 'Stop orders trigger a market order at the stop price; the execution price is not guaranteed.', ref: 'LOS eq-1-b' },
  { id: 'q-eq-002', topicId: 'equity', moduleId: 'eq-2', difficulty: 1, stem: 'In a price-weighted index, the largest influence comes from the stock with the:', options: ['largest market capitalization', 'highest share price', 'greatest trading volume'], answer: 1, explanation: 'Price-weighted (e.g., DJIA): weight is proportional to price per share, regardless of company size.', ref: 'LOS eq-2-a' },
  { id: 'q-eq-003', topicId: 'equity', moduleId: 'eq-3', difficulty: 2, stem: 'If markets are semi-strong-form efficient, which analysis cannot consistently generate abnormal returns?', options: ['technical analysis only', 'both technical and fundamental analysis of public data', 'trading on inside information'], answer: 1, explanation: 'Semi-strong prices reflect all public information — past prices (TA) and public fundamentals (FA) are already priced.', ref: 'LOS eq-3-a' },
  { id: 'q-eq-004', topicId: 'equity', moduleId: 'eq-8', difficulty: 2, stem: 'A stock pays D₁ = 3.00, has required return 11% and growth 5%. Its Gordon growth value is:', options: ['27.27', '50.00', '52.50'], answer: 1, explanation: 'V = 3/(0.11 − 0.05) = 50. Use D₁ and the (r − g) denominator.', ref: 'LOS eq-8-b' },
  { id: 'q-eq-005', topicId: 'equity', moduleId: 'eq-10', difficulty: 2, stem: 'All else equal, a higher required rate of return implies a justified P/E that is:', options: ['higher', 'lower', 'unchanged'], answer: 1, explanation: 'P/E = (1−b)/(r−g): a larger r widens the denominator, lowering the multiple.', ref: 'LOS eq-10-b' },
  { id: 'q-eq-006', topicId: 'equity', moduleId: 'eq-10', difficulty: 1, stem: 'Which multiple is most appropriate for a young company with negative earnings and negative book value?', options: ['P/E', 'P/S', 'P/B'], answer: 1, explanation: 'Sales are almost never negative, so P/S stays meaningful when earnings and book value fail.', ref: 'LOS eq-10-a' },
  { id: 'q-eq-007', topicId: 'equity', moduleId: 'eq-1', difficulty: 2, stem: 'An investor buys shares at $40 using 50% margin. Ignoring costs, if the price rises to $46 the return on equity invested is:', options: ['15%', '30%', '7.5%'], answer: 1, explanation: 'Price return 15% × leverage 2 (= 1/0.5) = 30%.', ref: 'LOS eq-1-b' },
  { id: 'q-eq-008', topicId: 'equity', moduleId: 'eq-6', difficulty: 2, stem: 'In Porter’s Five Forces, the entry of many low-cost competitors most directly increases:', options: ['supplier bargaining power', 'the threat of new entrants and rivalry, pressuring margins', 'buyer switching costs'], answer: 1, explanation: 'More entrants raise rivalry and the threat of entry, which competes away margins.', ref: 'LOS eq-6-a' },
  { id: 'q-eq-009', topicId: 'equity', moduleId: 'eq-12', difficulty: 3, stem: 'Compared with the CAPM, a multi-factor model of required return:', options: ['uses only the market factor', 'adds factors such as size, value and momentum', 'ignores systematic risk'], answer: 1, explanation: 'Multi-factor models (introduced at Level I for 2027) add priced factors beyond the market to explain required return.', ref: 'LOS eq-12-a' },
  { id: 'q-eq-010', topicId: 'equity', moduleId: 'eq-11', difficulty: 2, stem: 'When reading an activist short seller’s bearish report, an analyst should recognize that the author:', options: ['has no financial interest in the outcome', 'holds a short position and benefits if the price falls', 'is regulated to present a balanced view'], answer: 1, explanation: 'Activist short sellers profit if the price falls, so their claims require independent verification.', ref: 'LOS eq-11-b' },

  /* ---------- Fixed Income ---------- */
  { id: 'q-fi-001', topicId: 'fixedincome', moduleId: 'fi-6', difficulty: 1, stem: 'A bond whose coupon rate is below its yield-to-maturity trades at:', options: ['a premium', 'a discount', 'par'], answer: 1, explanation: 'Coupon < required yield → price below face to compensate the investor.', ref: 'LOS fi-6-b' },
  { id: 'q-fi-002', topicId: 'fixedincome', moduleId: 'fi-2', difficulty: 2, stem: 'Relative to an otherwise identical option-free bond, a callable bond has:', options: ['a lower yield and higher price', 'a higher yield and lower price', 'the same yield but longer duration'], answer: 1, explanation: 'The call favours the issuer; investors demand extra yield (pay a lower price).', ref: 'LOS fi-2-a' },
  { id: 'q-fi-003', topicId: 'fixedincome', moduleId: 'fi-11', difficulty: 1, stem: 'A zero-coupon bond’s Macaulay duration equals:', options: ['zero', 'its time to maturity', 'half its time to maturity'], answer: 1, explanation: 'The single cash flow arrives at maturity, so the weighted-average time = maturity.', ref: 'LOS fi-11-a' },
  { id: 'q-fi-004', topicId: 'fixedincome', moduleId: 'fi-12', difficulty: 2, stem: 'Modified duration 6.0, convexity 45, yields fall 100 bps. The estimated price change is closest to:', options: ['+6.00%', '+6.23%', '+5.78%'], answer: 1, explanation: '+6 × 0.01 = 6.00% plus ½ × 45 × 0.01² = 0.225% → +6.23%. Convexity always adds.', ref: 'LOS fi-12-a' },
  { id: 'q-fi-005', topicId: 'fixedincome', moduleId: 'fi-7', difficulty: 3, stem: 'A corporate bond’s Z-spread is 180 bps and its OAS is 120 bps. The embedded option is most likely:', options: ['a put worth 60 bps to the investor', 'a call costing the investor 60 bps', 'worthless'], answer: 1, explanation: 'Option cost = Z − OAS = 60 bps > 0 → an issuer-friendly (call) option.', ref: 'LOS fi-7-a' },
  { id: 'q-fi-006', topicId: 'fixedincome', moduleId: 'fi-10', difficulty: 2, stem: 'An investor’s horizon is shorter than the bond’s Macaulay duration. The dominant risk is:', options: ['reinvestment risk', 'price risk', 'default risk'], answer: 1, explanation: 'Horizon < MacDur: rising rates hurt because the sale price falls before reinvestment gains catch up.', ref: 'LOS fi-10-a' },
  { id: 'q-fi-007', topicId: 'fixedincome', moduleId: 'fi-19', difficulty: 2, stem: 'When interest rates fall sharply, holders of mortgage pass-through securities face:', options: ['extension risk', 'contraction risk', 'inflation risk'], answer: 1, explanation: 'Homeowners refinance → prepayments accelerate → principal returns early (contraction).', ref: 'LOS fi-19-a' },
  { id: 'q-fi-008', topicId: 'fixedincome', moduleId: 'fi-14', difficulty: 1, stem: 'Expected loss on a bond with a 2% default probability and 40% recovery rate is closest to:', options: ['0.8% of exposure', '1.2% of exposure', '2.0% of exposure'], answer: 1, explanation: 'EL = PD × (1 − recovery) = 2% × 0.6 = 1.2%.', ref: 'LOS fi-14-a' },
  { id: 'q-fi-009', topicId: 'fixedincome', moduleId: 'fi-9', difficulty: 3, stem: '1-year spot 3%, 2-year spot 4%. The implied 1-year forward rate one year from now is closest to:', options: ['3.5%', '5.0%', '4.5%'], answer: 1, explanation: '(1.04)²/(1.03) − 1 = 5.01%. The forward sits above both spots on an upward curve.', ref: 'LOS fi-9-a' },
  { id: 'q-fi-010', topicId: 'fixedincome', moduleId: 'fi-17', difficulty: 2, stem: 'Credit tranching in a securitization primarily redistributes:', options: ['interest rate risk among tranches', 'credit (default) risk among tranches', 'currency risk among tranches'], answer: 1, explanation: 'Subordination (credit tranching) makes senior tranches safer at the juniors’ expense; time tranching handles prepayment risk.', ref: 'LOS fi-17-a' },

  /* ---------- Derivatives ---------- */
  { id: 'q-der-001', topicId: 'derivatives', moduleId: 'der-5', difficulty: 1, stem: 'The value of a forward contract at initiation is:', options: ['the present value of the forward price', 'zero', 'the spot price minus the forward price'], answer: 1, explanation: 'The forward price is set so neither party pays at inception — value starts at zero.', ref: 'LOS der-5-a' },
  { id: 'q-der-002', topicId: 'derivatives', moduleId: 'der-6', difficulty: 2, stem: 'Compared with forwards, futures contracts:', options: ['carry more counterparty risk', 'are marked to market daily through a clearinghouse', 'are customized between two parties'], answer: 1, explanation: 'Exchange trading, standardization, margin and daily settlement define futures.', ref: 'LOS der-6-a' },
  { id: 'q-der-003', topicId: 'derivatives', moduleId: 'der-5', difficulty: 1, stem: 'Spot = 60, r = 5%, T = 1 year, no income. The no-arbitrage forward price is:', options: ['57.14', '63.00', '60.00'], answer: 1, explanation: 'F = 60 × 1.05 = 63.', ref: 'LOS der-5-a' },
  { id: 'q-der-004', topicId: 'derivatives', moduleId: 'der-8', difficulty: 1, stem: 'The maximum loss for the buyer of a call option is:', options: ['unlimited', 'the premium paid', 'the strike price'], answer: 1, explanation: 'A long option can at most expire worthless — losing only the premium.', ref: 'LOS der-8-a' },
  { id: 'q-der-005', topicId: 'derivatives', moduleId: 'der-9', difficulty: 3, stem: 'Using put–call parity, a synthetic long call equals:', options: ['long put + long stock − PV(X) financed by borrowing', 'short put + short stock + lending', 'long put − long stock'], answer: 0, explanation: 'c = p + S − X/(1+r)^T: buy the put and stock, financing part by borrowing the PV of the strike.', ref: 'LOS der-9-a' },
  { id: 'q-der-006', topicId: 'derivatives', moduleId: 'der-10', difficulty: 2, stem: 'In the one-period binomial model, the option price is computed using:', options: ['the actual probabilities of up and down moves', 'risk-neutral probabilities and discounting at the risk-free rate', 'the expected return of the underlying stock'], answer: 1, explanation: 'π = (1+r−d)/(u−d); real-world probabilities and the stock’s expected return never enter the formula.', ref: 'LOS der-10-a' },
  { id: 'q-der-007', topicId: 'derivatives', moduleId: 'der-7', difficulty: 2, stem: 'A fixed-rate payer in a plain-vanilla interest rate swap benefits when:', options: ['interest rates fall', 'interest rates rise', 'the yield curve inverts'], answer: 1, explanation: 'Paying fixed and receiving floating gains value as the floating leg resets higher.', ref: 'LOS der-7-a' },
  { id: 'q-der-008', topicId: 'derivatives', moduleId: 'der-8', difficulty: 2, stem: 'All else equal, higher volatility of the underlying:', options: ['raises call values but lowers put values', 'raises both call and put values', 'lowers both call and put values'], answer: 1, explanation: 'Volatility raises the chance of finishing deep in the money while losses stay capped — good for both option types.', ref: 'LOS der-8-a' },

  /* ---------- Alternative Investments ---------- */
  { id: 'q-ai-001', topicId: 'alts', moduleId: 'ai-2', difficulty: 2, stem: 'A high-water mark provision ensures that:', options: ['the manager earns a minimum fee each year', 'incentive fees are paid only on gains above the previous peak value', 'investors can redeem at any time'], answer: 1, explanation: 'No incentive fee is due until earlier losses are recovered — investors don’t pay twice for the same gains.', ref: 'LOS ai-2-a' },
  { id: 'q-ai-002', topicId: 'alts', moduleId: 'ai-6', difficulty: 2, stem: 'Compared with investing in a single hedge fund, a fund-of-funds typically offers:', options: ['lower total fees', 'more diversification but an extra layer of fees', 'higher guaranteed returns'], answer: 1, explanation: 'Funds-of-funds add diversification and due diligence but stack their own fees on the underlying funds’.', ref: 'LOS ai-6-a' },
  { id: 'q-ai-003', topicId: 'alts', moduleId: 'ai-5', difficulty: 2, stem: 'A commodity futures market where futures prices exceed spot prices is in:', options: ['backwardation', 'contango', 'convergence'], answer: 1, explanation: 'Contango: futures > spot → negative roll yield for long futures investors.', ref: 'LOS ai-5-a' },
  { id: 'q-ai-004', topicId: 'alts', moduleId: 'ai-4', difficulty: 1, stem: 'A property has NOI of $300,000 and sells for $5,000,000. Its capitalization rate is:', options: ['16.7%', '6.0%', '3.0%'], answer: 1, explanation: 'Cap rate = NOI/price = 300k/5m = 6%.', ref: 'LOS ai-4-a' },
  { id: 'q-ai-005', topicId: 'alts', moduleId: 'ai-3', difficulty: 2, stem: 'The typical private-equity fund cash-flow pattern (the "J-curve") shows:', options: ['distributions first, capital calls later', 'capital calls first, distributions later', 'level cash flows throughout'], answer: 1, explanation: 'Early years: drawdowns and fees push returns negative; exits later drive the curve up.', ref: 'LOS ai-3-a' },
  { id: 'q-ai-006', topicId: 'alts', moduleId: 'ai-2', difficulty: 2, stem: 'Survivorship bias in hedge-fund indexes most likely causes reported returns to be:', options: ['understated', 'overstated', 'unbiased'], answer: 1, explanation: 'Failed funds drop out of the database, leaving only survivors — reported performance looks too good.', ref: 'LOS ai-2-a' },
  { id: 'q-ai-007', topicId: 'alts', moduleId: 'ai-7', difficulty: 2, stem: 'Which is a defining feature of most cryptocurrencies?', options: ['they are claims on a company’s cash flows', 'they are recorded on a distributed ledger (blockchain)', 'their prices are guaranteed by a central bank'], answer: 1, explanation: 'Cryptocurrencies run on distributed ledger technology; they are not claims on cash flows and are not central-bank guaranteed.', ref: 'LOS ai-7-a' },

  /* ---------- Portfolio Management ---------- */
  { id: 'q-pm-001', topicId: 'portfolio', moduleId: 'pm-1', difficulty: 1, stem: 'Diversification reduces portfolio risk whenever the correlation between assets is:', options: ['exactly +1', 'less than +1', 'exactly 0 or lower'], answer: 1, explanation: 'Any correlation below +1 makes portfolio σ less than the weighted average of the individual σs.', ref: 'LOS pm-1-a' },
  { id: 'q-pm-002', topicId: 'portfolio', moduleId: 'pm-1', difficulty: 2, stem: 'According to the CAPM, investors are compensated for bearing:', options: ['total risk', 'systematic risk only', 'unsystematic risk only'], answer: 1, explanation: 'Unsystematic risk can be diversified away for free, so the market does not pay for it.', ref: 'LOS pm-1-a' },
  { id: 'q-pm-003', topicId: 'portfolio', moduleId: 'pm-2', difficulty: 2, stem: 'Rf = 2%, E(Rm) = 8%, β = 1.5. The CAPM required return is:', options: ['9%', '11%', '12%'], answer: 1, explanation: '2% + 1.5 × (8% − 2%) = 2% + 9% = 11%. Use the market risk premium, not the market return.', ref: 'LOS pm-2-a' },
  { id: 'q-pm-004', topicId: 'portfolio', moduleId: 'pm-2', difficulty: 2, stem: 'A security plotting above the security market line is best described as:', options: ['overvalued', 'undervalued', 'correctly priced'], answer: 1, explanation: 'Its expected return exceeds the CAPM-required return for its beta — a buy.', ref: 'LOS pm-2-a' },
  { id: 'q-pm-005', topicId: 'portfolio', moduleId: 'pm-2', difficulty: 3, stem: 'Which measure is most appropriate for evaluating a poorly diversified portfolio?', options: ['Treynor ratio', 'Sharpe ratio', 'Jensen’s alpha'], answer: 1, explanation: 'Sharpe uses total risk (σ), which matters when unsystematic risk has not been diversified away. Treynor/alpha use beta only.', ref: 'LOS pm-2-a' },
  { id: 'q-pm-006', topicId: 'portfolio', moduleId: 'pm-4', difficulty: 2, stem: 'In an IPS, a client’s ability to take risk is determined mainly by:', options: ['personality and past experiences', 'wealth, time horizon and income needs', 'the advisor’s market outlook'], answer: 1, explanation: 'Ability = financial capacity; willingness = psychology. When they conflict, use the more conservative and educate the client.', ref: 'LOS pm-4-a' },
  { id: 'q-pm-007', topicId: 'portfolio', moduleId: 'pm-5', difficulty: 2, stem: 'Overweighting recent, vivid news when estimating probabilities reflects which bias?', options: ['anchoring', 'availability', 'endowment'], answer: 1, explanation: 'Availability bias: what is vivid or recent is easiest to recall and gets overweighted.', ref: 'LOS pm-5-a' },
  { id: 'q-pm-008', topicId: 'portfolio', moduleId: 'pm-6', difficulty: 2, stem: 'A one-week 5% VaR of $1 million means:', options: ['the maximum possible weekly loss is $1 million', 'there is a 5% chance of losing at least $1 million in a week', 'losses will exceed $1 million in exactly 5 of every 100 weeks'], answer: 1, explanation: 'VaR is a minimum loss at the stated probability — it says nothing about how bad the tail can get.', ref: 'LOS pm-6-a' },
  { id: 'q-pm-009', topicId: 'portfolio', moduleId: 'pm-3', difficulty: 1, stem: 'The steps of the portfolio management process in order are:', options: ['execution, planning, feedback', 'planning, execution, feedback', 'feedback, planning, execution'], answer: 1, explanation: 'Write the IPS first (planning), build the portfolio (execution), then monitor and rebalance (feedback).', ref: 'LOS pm-3-a' },
  { id: 'q-pm-010', topicId: 'portfolio', moduleId: 'pm-5', difficulty: 2, stem: 'Emotional biases, compared with cognitive errors, are generally:', options: ['easier to correct with better information', 'harder to correct and often better accommodated than eliminated', 'irrelevant for wealthy clients'], answer: 1, explanation: 'Cognitive errors respond to education; emotional biases stem from feelings and usually must be accommodated.', ref: 'LOS pm-5-a' },

  /* ===== Expanded coverage: modules previously untested + extra depth ===== */
  /* Ethics */
  { id: 'q-eth-009', topicId: 'ethics', moduleId: 'eth-1', difficulty: 1, stem: 'Which best distinguishes ethical standards from legal standards?', options: ['ethics and law always require identical conduct', 'some legal acts can still be unethical, and ethics may demand more than the law', 'ethics is only relevant where no law exists'], answer: 1, explanation: 'Laws are a floor; ethical conduct can require more, and an act can be legal yet unethical.', ref: 'LOS eth-1-b' },
  { id: 'q-eth-010', topicId: 'ethics', moduleId: 'eth-2', difficulty: 1, stem: 'The Code of Ethics and Standards of Professional Conduct consist of:', options: ['seven Code components and six Standards', 'six Code components and seven Standards', 'six Code components and six Standards'], answer: 1, explanation: 'The Code has six components; the Standards of Professional Conduct number seven (I–VII).', ref: 'LOS eth-2-a' },
  { id: 'q-eth-011', topicId: 'ethics', moduleId: 'eth-10', difficulty: 2, stem: 'An analyst is unsure whether an action violates the Standards. The most appropriate first step is to:', options: ['proceed, since intent matters most', 'identify the relevant Standard(s) and choose the most conservative compliant action', 'ask a colleague to take the action instead'], answer: 1, explanation: 'Work the scenario against the sub-standards and select the most conservative compliant course (disclose, dissociate, decline).', ref: 'LOS eth-10-b' },
  /* Quant */
  { id: 'q-qm-014', topicId: 'quant', moduleId: 'qm-1', difficulty: 1, stem: 'A stock bought at 50 is sold at 54 after paying a 1 dividend. The holding-period return is:', options: ['8%', '10%', '6%'], answer: 1, explanation: 'HPR = (54 − 50 + 1)/50 = 5/50 = 10%.', ref: 'LOS qm-1-a' },
  { id: 'q-qm-015', topicId: 'quant', moduleId: 'qm-6', difficulty: 2, stem: 'Two events are independent if:', options: ['P(A | B) = P(A)', 'P(A and B) = 0', 'P(A) + P(B) = 1'], answer: 0, explanation: 'Independence means B does not change the probability of A: P(A|B) = P(A). Mutually exclusive events have P(A and B) = 0.', ref: 'LOS qm-6-a' },
  /* Economics */
  { id: 'q-econ-009', topicId: 'econ', moduleId: 'econ-7', difficulty: 2, stem: 'A country that imports far more than it exports most likely runs a:', options: ['current account surplus', 'current account deficit financed by capital inflows', 'balanced current account'], answer: 1, explanation: 'A trade/current-account deficit is mirrored by a financial-account surplus (net capital inflows).', ref: 'LOS econ-7-a' },
  /* FSA */
  { id: 'q-fsa-011', topicId: 'fsa', moduleId: 'fsa-1', difficulty: 1, stem: 'An unqualified (clean) auditor’s opinion indicates that the financial statements are:', options: ['guaranteed free of any error or fraud', 'fairly presented in accordance with the applicable accounting standards', 'prepared on a cash basis'], answer: 1, explanation: 'A clean opinion gives reasonable assurance of fair presentation under GAAP/IFRS — not a guarantee against all fraud.', ref: 'LOS fsa-1-b' },
  { id: 'q-fsa-012', topicId: 'fsa', moduleId: 'fsa-2', difficulty: 2, stem: 'Under the revenue recognition model, revenue is recognized when:', options: ['cash is collected', 'a performance obligation is satisfied', 'the contract is signed'], answer: 1, explanation: 'Revenue is recognized as performance obligations are satisfied (control transfers), not necessarily when cash moves.', ref: 'LOS fsa-2-a' },
  { id: 'q-fsa-013', topicId: 'fsa', moduleId: 'fsa-10', difficulty: 2, stem: 'A widening gap between reported net income and operating cash flow is a potential sign of:', options: ['conservative accounting', 'low-quality earnings / aggressive accruals', 'higher dividend capacity'], answer: 1, explanation: 'Earnings growing faster than cash flow can signal aggressive revenue timing or accruals — an earnings-quality red flag.', ref: 'LOS fsa-10-b' },
  { id: 'q-fsa-014', topicId: 'fsa', moduleId: 'fsa-12', difficulty: 2, stem: 'Forecasting revenue as market size × market share is a:', options: ['bottom-up approach', 'top-down approach', 'hybrid residual approach'], answer: 1, explanation: 'Top-down starts from the market and applies a share; bottom-up builds from units × price at the company level.', ref: 'LOS fsa-12-b' },
  /* Corporate Issuers */
  { id: 'q-ci-009', topicId: 'corp', moduleId: 'ci-1', difficulty: 1, stem: 'A key advantage of the corporate (limited company) form is:', options: ['unlimited liability for owners', 'limited liability and easier access to capital', 'automatic dissolution when an owner exits'], answer: 1, explanation: 'Shareholders enjoy limited liability and the firm has perpetual life and broad access to capital.', ref: 'LOS ci-1-a' },
  { id: 'q-ci-010', topicId: 'corp', moduleId: 'ci-2', difficulty: 2, stem: 'The conflict in which managers pursue their own interests rather than shareholders’ is a:', options: ['principal–agent problem', 'network externality', 'pecking-order effect'], answer: 0, explanation: 'The manager (agent) may not act in the owners’ (principals’) best interest — the classic principal–agent problem.', ref: 'LOS ci-2-a' },
  { id: 'q-ci-011', topicId: 'corp', moduleId: 'ci-8', difficulty: 2, stem: 'A subscription pricing model most directly aims to:', options: ['maximize one-time transaction size', 'generate recurring revenue and predictable cash flow', 'eliminate customer switching costs'], answer: 1, explanation: 'Subscriptions create recurring, more predictable revenue and can raise switching costs.', ref: 'LOS ci-8-a' },
  /* Equities */
  { id: 'q-eq-011', topicId: 'equity', moduleId: 'eq-4', difficulty: 1, stem: 'Compared with common shareholders, preferred shareholders generally have:', options: ['greater voting power', 'a fixed dividend and priority over common in liquidation', 'a residual claim only'], answer: 1, explanation: 'Preferred stock typically pays a fixed dividend and ranks ahead of common; it is usually non-voting.', ref: 'LOS eq-4-a' },
  { id: 'q-eq-012', topicId: 'equity', moduleId: 'eq-5', difficulty: 1, stem: 'The total return to an equity investor comes from:', options: ['capital appreciation only', 'capital appreciation plus dividend (and reinvestment) income', 'coupon payments'], answer: 1, explanation: 'Equity total return = price change + dividends (+ reinvestment, and any currency effect for foreign holdings).', ref: 'LOS eq-5-a' },
  { id: 'q-eq-013', topicId: 'equity', moduleId: 'eq-7', difficulty: 2, stem: 'Building base, bull and bear cases and weighting them by probability is called:', options: ['sensitivity analysis', 'scenario analysis', 'common-size analysis'], answer: 1, explanation: 'Scenario analysis assigns probabilities across discrete cases; the 2027 curriculum treats it as standard valuation practice.', ref: 'LOS eq-7-b' },
  { id: 'q-eq-014', topicId: 'equity', moduleId: 'eq-9', difficulty: 3, stem: 'In a DCF, the terminal value usually:', options: ['is negligible relative to explicit-period cash flows', 'accounts for a large share of total value, so the long-run growth rate must be tested carefully', 'should exceed the economy’s growth rate'], answer: 1, explanation: 'Terminal value dominates most DCFs; long-run g must be reasonable (below economy growth).', ref: 'LOS eq-9-b' },
  /* Fixed Income */
  { id: 'q-fi-011', topicId: 'fixedincome', moduleId: 'fi-1', difficulty: 1, stem: 'A negative bond covenant is one that:', options: ['requires the issuer to take specified actions', 'restricts the issuer from certain actions (e.g., extra debt, dividends)', 'sets the coupon rate'], answer: 1, explanation: 'Negative (restrictive) covenants limit the issuer; affirmative covenants require actions.', ref: 'LOS fi-1-a' },
  { id: 'q-fi-012', topicId: 'fixedincome', moduleId: 'fi-3', difficulty: 1, stem: 'Most bonds trade in the secondary market:', options: ['on centralized exchanges like stocks', 'over the counter through dealers', 'only at issuance'], answer: 1, explanation: 'Bond secondary trading is predominantly OTC and dealer-based, with liquidity varying by issue.', ref: 'LOS fi-3-a' },
  { id: 'q-fi-013', topicId: 'fixedincome', moduleId: 'fi-4', difficulty: 1, stem: 'Commercial paper is best described as:', options: ['long-term secured corporate debt', 'short-term unsecured corporate funding', 'a government inflation-linked bond'], answer: 1, explanation: 'Commercial paper is short-term, usually unsecured funding used by corporate issuers.', ref: 'LOS fi-4-a' },
  { id: 'q-fi-014', topicId: 'fixedincome', moduleId: 'fi-5', difficulty: 2, stem: 'For an inflation-linked government bond (e.g., TIPS), inflation adjustments are typically applied to the:', options: ['coupon rate', 'principal, which then drives the coupon amount', 'maturity date'], answer: 1, explanation: 'The principal is indexed to inflation; the fixed coupon rate is applied to the adjusted principal.', ref: 'LOS fi-5-a' },
  { id: 'q-fi-015', topicId: 'fixedincome', moduleId: 'fi-8', difficulty: 2, stem: 'The coupon on a floating-rate note resets each period to:', options: ['a fixed rate set at issuance', 'a reference rate plus the quoted margin', 'the bond’s yield to maturity'], answer: 1, explanation: 'Floater coupon = reference rate + quoted margin; the price stays near par around reset dates.', ref: 'LOS fi-8-a' },
  { id: 'q-fi-016', topicId: 'fixedincome', moduleId: 'fi-13', difficulty: 3, stem: 'For a bond with an embedded option, the appropriate interest-rate risk measure is:', options: ['Macaulay duration', 'effective duration', 'current yield'], answer: 1, explanation: 'Effective duration uses curve shifts and accounts for cash flows that change with rates — required for embedded options.', ref: 'LOS fi-13-a' },
  { id: 'q-fi-017', topicId: 'fixedincome', moduleId: 'fi-15', difficulty: 2, stem: 'A sovereign’s local-currency rating can exceed its foreign-currency rating mainly because the government can:', options: ['default only on local debt', 'print its own currency to service local-currency debt', 'ignore inflation'], answer: 1, explanation: 'A government controls its own currency, giving more flexibility to service local-currency obligations.', ref: 'LOS fi-15-a' },
  { id: 'q-fi-018', topicId: 'fixedincome', moduleId: 'fi-16', difficulty: 1, stem: 'The "four Cs" of traditional credit analysis are capacity, collateral, covenants and:', options: ['character', 'convexity', 'coupon'], answer: 0, explanation: 'Capacity, collateral, covenants and character.', ref: 'LOS fi-16-a' },
  { id: 'q-fi-019', topicId: 'fixedincome', moduleId: 'fi-18', difficulty: 2, stem: 'Compared with a typical ABS, a covered bond is generally safer because it offers:', options: ['no recourse to the issuer', 'dual recourse — to the cover pool and the issuer', 'a government guarantee'], answer: 1, explanation: 'Covered bonds stay on the issuer’s balance sheet and give investors dual recourse.', ref: 'LOS fi-18-a' },
  /* Derivatives */
  { id: 'q-der-009', topicId: 'derivatives', moduleId: 'der-1', difficulty: 1, stem: 'Relative to over-the-counter derivatives, exchange-traded derivatives are:', options: ['customized with more counterparty risk', 'standardized and cleared, reducing counterparty risk', 'unavailable to hedgers'], answer: 1, explanation: 'Exchange-traded contracts are standardized and centrally cleared, cutting counterparty risk.', ref: 'LOS der-1-a' },
  { id: 'q-der-010', topicId: 'derivatives', moduleId: 'der-2', difficulty: 1, stem: 'An option is best classified as a:', options: ['forward commitment', 'contingent claim', 'money-market instrument'], answer: 1, explanation: 'Options are contingent claims — the buyer has a right, not an obligation. Forwards/futures/swaps are forward commitments.', ref: 'LOS der-2-a' },
  { id: 'q-der-011', topicId: 'derivatives', moduleId: 'der-3', difficulty: 2, stem: 'Market participants who exploit price discrepancies to enforce the law of one price are:', options: ['hedgers', 'arbitrageurs', 'speculators'], answer: 1, explanation: 'Arbitrageurs trade away mispricings; hedgers transfer risk and speculators take it.', ref: 'LOS der-3-a' },
  { id: 'q-der-012', topicId: 'derivatives', moduleId: 'der-4', difficulty: 2, stem: 'For a dividend-paying stock, the no-arbitrage forward price, relative to a non-dividend stock, is:', options: ['higher, because carrying costs rise', 'lower, because the benefit of dividends is subtracted', 'unchanged'], answer: 1, explanation: 'Benefits of holding the underlying (dividends) reduce the forward price under cost-of-carry.', ref: 'LOS der-4-a' },
  /* Alternatives */
  { id: 'q-ai-008', topicId: 'alts', moduleId: 'ai-1', difficulty: 1, stem: 'Which is a common feature of alternative investments?', options: ['high liquidity and daily pricing', 'illiquidity, less regulation and potential diversification', 'guaranteed returns'], answer: 1, explanation: 'Alternatives are typically illiquid, less regulated/transparent, and can add diversification.', ref: 'LOS ai-1-a' },
];

/* quick accessors */
window.CFA = window.CFA || {};
window.CFA.questions = {
  all() { return window.QUESTIONS; },
  byTopic(id) { return window.QUESTIONS.filter((q) => q.topicId === id); },
  byModule(id) { return window.QUESTIONS.filter((q) => q.moduleId === id); },
  countByModule() {
    const m = {};
    window.QUESTIONS.forEach((q) => { m[q.moduleId] = (m[q.moduleId] || 0) + 1; });
    return m;
  },
};
